using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
            // Preserve the old name so existing documents (and direct SQL queries
            // that reference c.Discriminator) keep working without a data migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "EntityType|Key" to just "Key".
            // Opt back into the legacy format so existing ids ("Product|123") still resolve.
            entity.HasPartitionKey(p => p.Id);
        });

        // Use the EF Core 8 id format ("EntityType|Key") for all entities.
        foreach (var entityType in modelBuilder.Model.GetEntityTypes())
        {
            entityType.SetIdValueGeneratorFactory((p, t) =>
                new Microsoft.EntityFrameworkCore.Cosmos.ValueGeneration.Internal
                    .IdValueGenerator());
        }
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

